import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{r as c,o,c as r,d as h,a as e,b as t,e as d,w as n,f as i}from"./app-c9a3714a.js";const f="/assets/08-series-1-5d7f9499.svg",g={},x=e("div",{class:"hint-container tip"},[e("p",{class:"hint-container-title"},"读前须知"),e("p",null,"需要第 05 篇的平坦格和第 07 篇的摘要求解。本篇在事实边上添加值变换，让不同调用者复用同一摘要，得到各自的结果。")],-1),p=i(`<h2 id="_1-让事实携带值" tabindex="-1"><a class="header-anchor" href="#_1-让事实携带值" aria-hidden="true">#</a> 1. 让事实携带值</h2><p>下面使用数学整数的伪代码，不涉及机器整数溢出：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>calc(p):
    a = p + 2
    b = a * 5
    return b

u = calc(1)    // 调用 A
v = calc(4)    // 调用 B
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两次调用分别得到 u=15、v=30。calc 的计算过程相同，可以先汇总为一个变换，再分别代入实参。</p><p>在方法内部选择有限事实域 <code>D={p,a,b,ret}</code>。<strong>环境</strong> <code>ρ:D→L</code> 将每个事实映射到抽象值；例如 <code>ρ(p)=1</code>。L 包含 <code>⊥</code>、每个整数常量及 <code>⊤</code>，沿用 <code>⊥ ⊑ c ⊑ ⊤</code> 的顺序。</p>`,5),y={href:"https://research.cs.wisc.edu/wpis/abstracts/tcs96b.abs.html",target:"_blank",rel:"noopener noreferrer"},u=i('<h2 id="_2-事实依赖与边函数" tabindex="-1"><a class="header-anchor" href="#_2-事实依赖与边函数" aria-hidden="true">#</a> 2. 事实依赖与边函数</h2><p>每条事实边上的值变换叫<strong>边函数（edge function）</strong>，描述沿这条边传播时值怎样变化：</p><table><thead><tr><th style="text-align:left;">语句</th><th style="text-align:left;">事实依赖</th><th style="text-align:left;">边函数</th><th style="text-align:left;">输入为 1 时的过程</th></tr></thead><tbody><tr><td style="text-align:left;"><code>a=p+2</code></td><td style="text-align:left;"><code>p→a</code></td><td style="text-align:left;"><code>f(t)=t+2</code></td><td style="text-align:left;">a=3</td></tr><tr><td style="text-align:left;"><code>b=a*5</code></td><td style="text-align:left;"><code>a→b</code></td><td style="text-align:left;"><code>g(t)=5t</code></td><td style="text-align:left;">b=15</td></tr><tr><td style="text-align:left;"><code>return b</code></td><td style="text-align:left;"><code>b→ret</code></td><td style="text-align:left;"><code>id(t)=t</code></td><td style="text-align:left;">返回 15</td></tr></tbody></table><p>表中省略了其他未修改事实的恒等边。赋值覆盖左侧旧值，因此要删除左侧的旧值边。</p><p><code>p→a</code> 表示 a 依赖 p，<code>f(t)=t+2</code> 则计算值的变化。也可写成 <code>λt.t+2</code>，读作“将 t 映射到 t 加二的函数”；小写 λ 是匿名函数记号，大写 Λ 则是 IFDS 的辅助事实。</p><figure><img src="'+f+'" alt="沿事实依赖组合加二与乘五的值变换" tabindex="0" loading="lazy"><figcaption>沿事实依赖组合加二与乘五的值变换</figcaption></figure>',6),_={href:"https://github.com/Scrates1/Scrates1.github.io/blob/main/src/static-analysis/assets/08-series-1.mmd",target:"_blank",rel:"noopener noreferrer"},b=i(`<p>实线表示单步依赖及值变换，虚线汇总了整段计算。</p><h2 id="_3-底值、未知值与常量生成" tabindex="-1"><a class="header-anchor" href="#_3-底值、未知值与常量生成" aria-hidden="true">#</a> 3. 底值、未知值与常量生成</h2><p>将算术函数扩展到未知与底值，规则如下：</p><table><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">输入 <code>⊥</code></th><th style="text-align:left;">输入常量 c</th><th style="text-align:left;">输入 <code>⊤</code></th></tr></thead><tbody><tr><td style="text-align:left;">恒等</td><td style="text-align:left;"><code>⊥</code></td><td style="text-align:left;">c</td><td style="text-align:left;"><code>⊤</code></td></tr><tr><td style="text-align:left;">加 2</td><td style="text-align:left;"><code>⊥</code></td><td style="text-align:left;">c+2</td><td style="text-align:left;"><code>⊤</code></td></tr><tr><td style="text-align:left;">乘 5</td><td style="text-align:left;"><code>⊥</code></td><td style="text-align:left;">5c</td><td style="text-align:left;"><code>⊤</code></td></tr><tr><td style="text-align:left;">常量产生 k</td><td style="text-align:left;"><code>⊥</code></td><td style="text-align:left;">k</td><td style="text-align:left;">k</td></tr></tbody></table><p>底值表示没有有效贡献。常量赋值 <code>a=1</code> 从辅助事实 Λ 向 a 生成值；为此，Λ 携带固定的非底占位值 <code>★</code>，常量产生函数将它映射到 k。<code>★</code> 不代表程序常量，沿辅助恒等边保持不变。</p><p>“加 2”和数学整数上的“乘 5”都保持不同常量不同，因此对单常量域的 Join 分配：两个不同常量先合成未知，或分别变换再合成未知，结果一致。</p><p>截断除法可能把两个不同常量映射到同一个常量，Java 的有限位宽也会改变某些运算的性质。因此，每种抽象变换都需要检查 IDE 的条件；无法精确表示的操作可采用满足条件的保守近似。</p><h2 id="_4-同一路径组合-多条路径合并" tabindex="-1"><a class="header-anchor" href="#_4-同一路径组合-多条路径合并" aria-hidden="true">#</a> 4. 同一路径组合，多条路径合并</h2><h3 id="顺序执行-函数组合" tabindex="-1"><a class="header-anchor" href="#顺序执行-函数组合" aria-hidden="true">#</a> 顺序执行：函数组合</h3><p>先 f 后 g，写作 <code>g∘f</code>，读作“g 复合 f”：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>j(t) = g(f(t)) = 5(t+2)
j(1) = 15
j(4) = 30
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>组合顺序很重要。<code>f(g(t))=5t+2</code> 是先乘五后加二，已经换成另一段程序。</p><h3 id="分支汇合-逐点合并" tabindex="-1"><a class="header-anchor" href="#分支汇合-逐点合并" aria-hidden="true">#</a> 分支汇合：逐点合并</h3><p>如果另一条路径先加 4 再乘 5，那么有 <code>j₁(t)=5(t+2)</code>、<code>j₂(t)=5(t+4)</code>。汇总函数定义为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>(j₁ ⊔ j₂)(t) = j₁(t) ⊔ j₂(t)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>代入 t=1，两个结果为 15、25，合并为未知。两条路径若都算出 15，就保留 15。</p><p>函数表示必须对组合与逐点合并封闭、能判等，并保证更新收敛；仅有值格的有限高度还不够。本例的线性函数组合后仍可用系数表示，但合并未必如此：<code>t+2</code> 与 <code>2t</code> 在 t=2 时都为 4，其他整数输入上结果不同，合并应保留这个交点，不能直接当作处处未知。</p>`,17),m={href:"https://research.cs.wisc.edu/wpis/papers/tcs96b.pdf",target:"_blank",rel:"noopener noreferrer"},v={href:"https://research.cs.wisc.edu/wpis/papers/tr1470.pdf",target:"_blank",rel:"noopener noreferrer"},k=i('<h2 id="_5-从边函数到跳转函数" tabindex="-1"><a class="header-anchor" href="#_5-从边函数到跳转函数" aria-hidden="true">#</a> 5. 从边函数到跳转函数</h2><p>**跳转函数（jump function）**汇总过程入口到某个目标事实的值变换：沿路径组合边函数，再合并多条路径。它相当于第 07 篇的路径边附带一个函数，描述“从入口到这里，值怎样变化”。</p><p>写成四元组 <code>〈d₁,n,d₂,j〉</code>：</p><ul><li>d₁：该过程入口的源事实。</li><li>n：目标程序点，决定所属过程。</li><li>d₂：目标事实。</li><li>j：入口值到目标值的汇总函数。</li></ul><p>对 calc，得到：</p><table><thead><tr><th style="text-align:left;">目标位置</th><th style="text-align:left;">跳转函数条目</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">加法之后</td><td style="text-align:left;"><code>〈p,n₁,a,t↦t+2〉</code></td><td style="text-align:left;">入口 p 到 a</td></tr><tr><td style="text-align:left;">乘法之后</td><td style="text-align:left;"><code>〈p,n₂,b,t↦5(t+2)〉</code></td><td style="text-align:left;">入口 p 到 b</td></tr><tr><td style="text-align:left;">方法出口</td><td style="text-align:left;"><code>〈p,exit,ret,t↦5(t+2)〉</code></td><td style="text-align:left;">入口 p 到返回值</td></tr></tbody></table><p>出口处的汇总组成过程摘要。A、B 分别把 1、4 代入同一个摘要，就能保留各自的返回值。</p><h2 id="_6-两阶段求解-先汇总函数-再代入值" tabindex="-1"><a class="header-anchor" href="#_6-两阶段求解-先汇总函数-再代入值" aria-hidden="true">#</a> 6. 两阶段求解：先汇总函数，再代入值</h2>',8),j={href:"https://research.cs.wisc.edu/wpis/papers/tcs96b.pdf",target:"_blank",rel:"noopener noreferrer"},I=e("code",null,"1⊔4=⊤",-1),D=e("h3",{id:"阶段一-传播与汇总函数",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#阶段一-传播与汇总函数","aria-hidden":"true"},"#"),t(" 阶段一：传播与汇总函数")],-1),B=e("ol",null,[e("li",null,"在过程入口的同一事实上建立恒等跳转函数。"),e("li",null,"遇到普通边，按执行顺序组合当前跳转函数和边函数。"),e("li",null,"多条路径到同一条目时逐点合并；条目改变才继续调度。"),e("li",null,"到达出口，生成或更新摘要，并应用到匹配的调用返回位置。"),e("li",null,"与 IFDS 一样，处理“调用先到”和“摘要先到”两种时序，直到函数条目稳定。")],-1),E=e("code",null,"Λ→p",-1),w=e("code",null,"k₁",-1),A=e("code",null,"k₄",-1),S=e("code",null,"id",-1),L=e("code",null,"〈Λ,entry,Λ,id〉",-1),F=i('<table><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">当前任务</th><th style="text-align:left;">新条目</th><th style="text-align:left;">本次计算 / 后续动作</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">从种子出发</td><td style="text-align:left;"><code>〈Λ, main入口, Λ, id〉</code></td><td style="text-align:left;">沿 main 的普通边到达 A</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">A 调用 <code>calc(1)</code></td><td style="text-align:left;">被调入口 <code>〈p, entry, p, id〉</code>；登记 Incoming(calc,p) ← A，附 <code>k₁</code></td><td style="text-align:left;">调度 calc 入口；旁路保留 Λ</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;"><code>a=p+2</code></td><td style="text-align:left;"><code>〈p, n₁, a, t↦t+2〉</code></td><td style="text-align:left;">组合 <code>id</code> 与边函数</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;"><code>b=a*5</code></td><td style="text-align:left;"><code>〈p, n₂, b, t↦5(t+2)〉</code></td><td style="text-align:left;">组合上一条与 <code>t↦5t</code></td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;"><code>return b</code> 到达出口</td><td style="text-align:left;"><code>〈p, exit, ret, t↦5(t+2)〉</code>，记为摘要 j</td><td style="text-align:left;">查 Incoming，把 j 应用到 A</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">应用摘要到 A</td><td style="text-align:left;"><code>〈Λ, retA, u, j∘k₁〉</code>，即 <code>t↦15</code></td><td style="text-align:left;">继续 main，到达 B</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">B 调用 <code>calc(4)</code></td><td style="text-align:left;"><code>〈p, entry, p, id〉</code> 已存在，不再传播；Incoming(calc,p) 追加 B，附 <code>k₄</code></td><td style="text-align:left;">摘要 j 已有，直接应用</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">应用摘要到 B</td><td style="text-align:left;"><code>〈Λ, retB, v, j∘k₄〉</code>，即 <code>t↦30</code></td><td style="text-align:left;">main 到达出口，队列为空</td></tr></tbody></table><p>第 7 步直接复用 j，calc 无需重算。若其他调度下 B 先于摘要到达，则先登记等待、摘要生成后再应用，最终条目相同。</p><h3 id="阶段二-传播入口值并求值" tabindex="-1"><a class="header-anchor" href="#阶段二-传播入口值并求值" aria-hidden="true">#</a> 阶段二：传播入口值并求值</h3><p>从种子的初值出发，利用已稳定的调用关系与跳转函数求出过程入口值，再对所需条目求值。</p><table><thead><tr><th style="text-align:left;">查询</th><th style="text-align:left;">计算</th><th style="text-align:left;">结果</th></tr></thead><tbody><tr><td style="text-align:left;">A 返回后的 u</td><td style="text-align:left;"><code>j(k₁(★))</code></td><td style="text-align:left;">15</td></tr><tr><td style="text-align:left;">B 返回后的 v</td><td style="text-align:left;"><code>j(k₄(★))</code></td><td style="text-align:left;">30</td></tr><tr><td style="text-align:left;">calc 内部 p 的跨调用汇总</td><td style="text-align:left;"><code>1 ⊔ 4</code></td><td style="text-align:left;"><code>⊤</code></td></tr></tbody></table><p>calc 内部 p 的跨调用汇总为未知，但调用者仍通过各自的实参与摘要得到 15、30。</p><h2 id="_7-普通常量传播的分配性限制" tabindex="-1"><a class="header-anchor" href="#_7-普通常量传播的分配性限制" aria-hidden="true">#</a> 7. 普通常量传播的分配性限制</h2><p>第 05 篇的两条路径分别为 <code>(x,y)=(2,3)</code>、<code>(3,2)</code>。执行 <code>z=x+y</code>：</p><ul><li>各自执行再合并：<code>5⊔5=5</code>。</li><li>先逐变量合并再执行：<code>⊤+⊤=⊤</code>。</li></ul><p>结果不等，环境变换不满足分配律，不能直接拆成单事实值传播。calc 则只使用常量、复制和满足条件的一元线性变换。</p><h2 id="本篇要点" tabindex="-1"><a class="header-anchor" href="#本篇要点" aria-hidden="true">#</a> 本篇要点</h2><ul><li><strong>边函数</strong>描述一步值变换，<strong>跳转函数</strong>汇总入口到目标事实的变换。</li><li>沿路径组合、路径间逐点合并；函数表示须封闭、可判等并保证收敛。</li><li>先汇总函数再求值，本例同一个摘要得到 u=15、v=30。</li><li>普通 <code>z=x+y</code> 的环境变换不满足分配律；每类运算都须检查 IDE 的适用条件。</li></ul><p>后续分为两个专题：第 09 篇用路径条件排除不可行路径，第 10 篇讨论跳转函数的存储与回收。</p>',13);function N(V,C){const l=c("RouterLink"),a=c("ExternalLinkIcon");return o(),r("div",null,[x,h(" more "),e("p",null,[t("**IDE（Interprocedural Distributive Environments）**在 "),d(l,{to:"/static-analysis/07-ifds.html"},{default:n(()=>[t("IFDS")]),_:1}),t(" 的事实关系上附加值变换，用环境记录各事实的抽象值。")]),p,e("p",null,[t("IDE 要求环境变换对合并满足分配律，并满足收敛条件（跳转函数不能无限次变化，第 4 节说明）；边函数要支持有效的求值、组合、合并和等价判定。以适当的两元素值编码事实的存在性，可以将 IFDS 表示为 IDE 的特例。"),e("a",y,[t("IDE 原始论文及作者摘要"),d(a)])]),u,e("p",null,[e("a",_,[t("查看可编辑图源"),d(a)])]),b,e("p",null,[t("**线性常量传播（linear constant propagation）**因此需要比两个线性系数更完整的函数表示。原论文采用额外分量表示合并后的函数，求值、组合与合并都有相应规则，见"),e("a",m,[t("原论文"),d(a)]),t("及"),e("a",v,[t("作者后续论文第 11 页"),d(a)]),t("。直接取顶函数是额外的保守近似，会丢掉交点处的常量；下文按精确组合与合并推演。")]),k,e("p",null,[t("经典 IDE 先汇总函数，再从种子初值求值，算法见"),e("a",j,[t("原论文"),d(a)]),t("。保留输入输出关系，就能避免先将 calc 的两个实参合为 "),I,t(" 后丢失区别。")]),D,B,e("p",null,[t("调用流边 "),E,t(" 上的 "),w,t("、"),A,t(" 分别从非底输入产生常量 1、4。沿用上一节的四元组与位置编号，"),S,t(" 为恒等函数；省略 calc 的 "),L,t(" 等辅助恒等条目，按"),d(l,{to:"/static-analysis/07-ifds.html"},{default:n(()=>[t("第 07 篇")]),_:1}),t("的调度方式推演：")]),F,e("p",null,[d(l,{to:"/static-analysis/07-ifds.html"},{default:n(()=>[t("上一篇：07 IFDS 事实传播")]),_:1}),t(" · "),d(l,{to:"/static-analysis/09-symbolic-execution-clang.html"},{default:n(()=>[t("下一篇：09 符号执行与 Clang")]),_:1}),t(" · "),d(l,{to:"/static-analysis/"},{default:n(()=>[t("返回系列总览")]),_:1})])])}const R=s(g,[["render",N],["__file","08-ide.html.vue"]]);export{R as default};
